package setup

import (
	"crypto/ed25519"
	"crypto/rand"
	"crypto/x509"
	"encoding/base64"
	"encoding/pem"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

// SecretClass says who provisions a secret file and how.
type SecretClass string

const (
	// SecretClassRandom secrets are generated by altctl: random bytes,
	// URL-safe base64.
	SecretClassRandom SecretClass = "random"
	// SecretClassOperatorProvided secrets come from outside Alt (third-party
	// API credentials, a keypair whose halves must match). altctl creates an
	// empty placeholder and keeps reporting it until the operator fills it.
	SecretClassOperatorProvided SecretClass = "operator-provided"
	// SecretClassPKIProvisioner secrets are step-ca JWK provisioner
	// passwords. The bytes only work once a provisioner is registered with
	// them, so altctl never writes one; PKIBootstrapScript creates the file
	// and registers the provisioner together.
	SecretClassPKIProvisioner SecretClass = "pki-provisioner"
	// SecretClassEd25519SigningKey is the PKCS#8 PEM private half of an
	// Ed25519 key pair; altctl writes it together with its Partner.
	// #nosec G101 -- secret class identifier, not a credential
	SecretClassEd25519SigningKey SecretClass = "ed25519-signing-key"
	// SecretClassEd25519VerifyKey is the SPKI PEM public half, written by
	// the same step as its signing key Partner.
	// #nosec G101 -- secret class identifier, not a credential
	SecretClassEd25519VerifyKey SecretClass = "ed25519-verify-key"
)

// PKIBootstrapScript is the repo-relative script that provisions every
// SecretClassPKIProvisioner secret.
const PKIBootstrapScript = "pki-agent/scripts/bootstrap-pki-provisioner.sh"

// SecretSpec defines a secret file and how it is provisioned.
type SecretSpec struct {
	Filename    string
	Description string
	Class       SecretClass
	Length      int    // bytes for random generation (default 32)
	Truncate    int    // if > 0, truncate the encoded output to this many characters
	Partner     string // other half of an Ed25519 key pair
}

// SecretsResult holds the outcome of a secrets generation run
type SecretsResult struct {
	Created []string
	Skipped []string
}

// PendingSecrets are the secrets `altctl init` cannot finish on its own.
type PendingSecrets struct {
	// OperatorProvided are missing or still-empty placeholders.
	OperatorProvided []SecretSpec
	// PKIProvisioner are missing or empty; PKIBootstrapScript creates them.
	PKIProvisioner []SecretSpec
}

// secretMeta is the per-secret provisioning strategy attached to a derived
// secret filename.
type secretMeta struct {
	Description string
	Class       SecretClass
	Length      int
	Truncate    int
	Partner     string
}

func randomSecret(description string) secretMeta {
	return secretMeta{Description: description, Class: SecretClassRandom, Length: 32}
}

func operatorSecret(description string) secretMeta {
	return secretMeta{Description: description, Class: SecretClassOperatorProvided}
}

