// pkiProvisionerSecret matches the per-subject provisioner password files
// PKIBootstrapScript writes (`pki-agent-<subject>-jwk.txt`).
var pkiProvisionerSecret = regexp.MustCompile(`^pki-agent-([a-z0-9-]+)-jwk\.txt$`)

func metaFor(name string) (secretMeta, bool) {
	if meta, ok := knownSecretMeta[name]; ok {
		return meta, true
	}
	if m := pkiProvisionerSecret.FindStringSubmatch(name); m != nil {
		return secretMeta{
			Description: fmt.Sprintf("step-ca JWK provisioner password for %s", m[1]),
			Class:       SecretClassPKIProvisioner,
		}, true
	}
	return secretMeta{}, false
}

// composeSecretsDoc decodes only the top-level "secrets:" key of a compose
// YAML document as a raw yaml.Node, mirroring internal/stack's
// composeFileDoc technique -- we only need the mapping's keys/values, not
// full anchor/alias resolution.
type composeSecretsDoc struct {
	Secrets yaml.Node `yaml:"secrets"`
}

// secretFileEntry is a single `secrets:` block entry: `name: {file: path}`.
type secretFileEntry struct {
	File string `yaml:"file"`
}

// secretNamesFromComposeFile reads a compose YAML file (compose/base.yaml)
// and returns the base filenames declared by its top-level secrets: block's
// `file: ../secrets/X.txt` entries, sorted for deterministic output. This
// is the single source of truth for which secret files `altctl init` must
// generate -- compose/base.yaml, not a hand-maintained Go list.
func secretNamesFromComposeFile(path string) ([]string, error) {
	// #nosec G304 -- path is compose/base.yaml from operator project root
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("reading compose file %s: %w", path, err)
	}

	var doc composeSecretsDoc
	if err := yaml.Unmarshal(data, &doc); err != nil {
		return nil, fmt.Errorf("parsing compose file %s: %w", path, err)
	}

	if doc.Secrets.Kind != yaml.MappingNode {
		return nil, fmt.Errorf("compose file %s has no top-level secrets: block", path)
	}

	var names []string
	for i := 0; i+1 < len(doc.Secrets.Content); i += 2 {
		valueNode := doc.Secrets.Content[i+1]
		var entry secretFileEntry
		if err := valueNode.Decode(&entry); err != nil || entry.File == "" {
			continue
		}
		base := filepath.Base(entry.File)
		if base == "." || base == ".." || base == string(filepath.Separator) {
			return nil, fmt.Errorf("invalid secret file path %q in %s", entry.File, path)
		}
		names = append(names, base)
	}
	sort.Strings(names)
	return names, nil
}

// specsFromNames builds SecretSpecs for the given secret filenames and
// fails on any name with no provisioning class.
func specsFromNames(names []string) ([]SecretSpec, error) {
	specs := make([]SecretSpec, 0, len(names))
	var unclassified []string
	for _, name := range names {
		meta, ok := metaFor(name)
		if !ok {
			unclassified = append(unclassified, name)
			continue
		}
		specs = append(specs, SecretSpec{
			Filename:    name,
			Description: meta.Description,
			Class:       meta.Class,
			Length:      meta.Length,
			Truncate:    meta.Truncate,
			Partner:     meta.Partner,
		})
	}
	if len(unclassified) > 0 {
		return nil, fmt.Errorf(
			"compose declares secrets altctl has no provisioning class for: %s (rebuild altctl, or classify them in knownSecretMeta as %s / %s / %s)",
			strings.Join(unclassified, ", "),
			SecretClassRandom, SecretClassOperatorProvided, SecretClassPKIProvisioner,
		)
	}
	return specs, nil
}

// DeriveSecretSpecs derives the full secret spec list from a compose base
// YAML file's secrets: block (e.g. compose/base.yaml). Exported so callers
// (and tests) can point it at a specific file instead of relying on
// DefaultSecretSpecs' runtime repo-root discovery.
func DeriveSecretSpecs(baseComposeFile string) ([]SecretSpec, error) {
	names, err := secretNamesFromComposeFile(baseComposeFile)
	if err != nil {
		return nil, err
	}
	return specsFromNames(names)
}

// findBaseComposeFile locates compose/base.yaml by walking up from the
// current working directory looking for a compose/base.yaml file directly
// (not just a directory named "compose" -- altctl/internal/compose is a Go
// package directory of that same name, which a looser check would match
// first when walking up from this package's own `go test` cwd). This works
// both for a real `altctl init` run (cwd somewhere under the repo) and for
// `go test` (cwd = this package's dir).
func findBaseComposeFile() (string, error) {
	cwd, err := os.Getwd()
	if err != nil {
		return "", err
	}
	dir := cwd
	for {
		candidate := filepath.Join(dir, "compose", "base.yaml")
		if _, err := os.Stat(candidate); err == nil {
			return candidate, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", fmt.Errorf("compose/base.yaml not found (walked up from %s)", cwd)
		}
		dir = parent
	}
}

// DefaultSecretSpecs returns the complete list of secret file
// specifications, derived at runtime from compose/base.yaml's secrets:
// block (single source of truth -- see secretNamesFromComposeFile), with
// each secret's provisioning class attached from knownSecretMeta.
//
// C2: this used to silently fall back to a 3-secret placeholder list when
// compose/base.yaml couldn't be located or parsed, and callers (cmd/init.go)
// both generated AND validated against that same shrunken list -- so `altctl
// init` reported "All required files present" while only 3 of the 24
// required secrets existed. Critical Rule 8 forbids exactly this shape of
// silent degrade for an unwired/broken dependency: a parse failure here must
// surface loudly, not be indistinguishable from "everything's fine." Callers
// now get the error and must hard-fail.
func DefaultSecretSpecs() ([]SecretSpec, error) {
	path, err := findBaseComposeFile()
	if err != nil {
		return nil, fmt.Errorf("locating compose/base.yaml: %w", err)
	}
	specs, err := DeriveSecretSpecs(path)
	if err != nil {
		return nil, fmt.Errorf("deriving secret specs from %s: %w", path, err)
	}
	return specs, nil
}

// secretFileMode is the mode every generated secret file gets. It is
// deliberately not owner-only: compose bind-mounts a `file:`-style secret
// into the container with the host file's mode intact, and Alt's images run
// as nonroot (UID 65532), which cannot read an owner-only file — the service
// then sees an empty secret and carries on with a placeholder instead of
// failing. On the production host the same directory is read by a second
// user as well (the CI runner stages from it over a shared group), so
// owner-only files break the deploy's staging step too. Everything with
// access to this directory is already trusted with its contents.
const secretFileMode = 0o644

// secretDirMode lets that same group traverse a directory altctl creates.
const secretDirMode = 0o750

// GenerateSecrets provisions the secret files altctl owns in dir: random
// secrets are generated, operator-provided secrets get an empty placeholder,
// pki-provisioner secrets are never written. Existing regular files are skipped;
// force regenerates existing random secrets only. All writes are confined to
// dir via os.OpenRoot and symlinks or non-regular targets are always rejected.
func GenerateSecrets(dir string, specs []SecretSpec, force bool) (*SecretsResult, error) {
	if err := ensureSecretsDir(dir); err != nil {
		return nil, err
	}

	root, err := os.OpenRoot(dir)
	if err != nil {
		return nil, fmt.Errorf("opening secrets directory %s: %w", dir, err)
	}
	defer func() { _ = root.Close() }()

	result := &SecretsResult{}

	for _, spec := range specs {
		if err := validateSecretFilename(spec.Filename); err != nil {
			return nil, err
		}
		if spec.Partner != "" {
			if err := validateSecretFilename(spec.Partner); err != nil {
				return nil, fmt.Errorf("secret %s partner: %w", spec.Filename, err)
			}
		}

		if spec.Class == SecretClassPKIProvisioner {
			continue
		}
		if spec.Class == SecretClassEd25519VerifyKey {
			continue
		}
		if spec.Class == SecretClassEd25519SigningKey {
			if spec.Partner == "" {
				return nil, fmt.Errorf("secret %s missing partner verify key filename", spec.Filename)
			}
			created, err := ensureEd25519KeyPair(root, spec.Filename, spec.Partner)
			if err != nil {
				return nil, fmt.Errorf("provisioning key pair %s / %s: %w", spec.Filename, spec.Partner, err)
			}
			if created {
				result.Created = append(result.Created, spec.Filename, spec.Partner)
			} else {
				result.Skipped = append(result.Skipped, spec.Filename, spec.Partner)
			}
			continue
		}

		exists, err := inspectSecretTarget(root, spec.Filename)
		if err != nil {
			return nil, fmt.Errorf("checking secret %s: %w", spec.Filename, err)
		}
		if exists && (!force || spec.Class != SecretClassRandom) {
			result.Skipped = append(result.Skipped, spec.Filename)
			continue
		}

		var content string
		switch spec.Class {
		case SecretClassRandom:
			length := spec.Length
			if length == 0 {
				length = 32
			}
			content, err = generateRandomSecret(length)
			if err != nil {
				return nil, fmt.Errorf("generating secret %s: %w", spec.Filename, err)
			}
			if spec.Truncate > 0 && len(content) > spec.Truncate {
				content = content[:spec.Truncate]
			}
		case SecretClassOperatorProvided:
		default:
			return nil, fmt.Errorf("secret %s has unknown provisioning class %q", spec.Filename, spec.Class)
		}

		overwrite := exists && force && spec.Class == SecretClassRandom
		if err := writeSecretFileInRoot(root, spec.Filename, []byte(content), overwrite); err != nil {
			return nil, err
		}
		result.Created = append(result.Created, spec.Filename)
	}

	return result, nil
}

// validateSecretFilename ensures name is a single base filename with no
// directory separators, traversal segments, or NUL bytes.
func validateSecretFilename(name string) error {
	if name == "" || name == "." || name == ".." {
		return fmt.Errorf("invalid secret filename %q", name)
	}
	if strings.ContainsRune(name, '\x00') || strings.ContainsAny(name, `/\`) {
		return fmt.Errorf("invalid secret filename %q: must be a single base filename", name)
	}
	if filepath.Base(name) != name || !filepath.IsLocal(name) {
		return fmt.Errorf("invalid secret filename %q: must be a single base filename", name)
	}
	return nil
}

// inspectSecretTarget checks name inside root via Lstat and rejects any
// symlink (dangling or live) or non-regular file (e.g. directory, FIFO).
func inspectSecretTarget(root *os.Root, name string) (bool, error) {
	info, err := root.Lstat(name)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return false, nil
		}
		return false, fmt.Errorf("inspecting %s: %w", name, err)
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return false, fmt.Errorf("refusing to write %s: symlink is not allowed", name)
	}
	if !info.Mode().IsRegular() {
		return false, fmt.Errorf("refusing to write %s: existing path is not a regular file", name)
	}
	return true, nil
}

// ensureEd25519KeyPair writes a PKCS#8 private key and its SPKI public key
// inside root unless both regular files already exist. Exactly one existing
// file is an error: a regenerated half would silently stop matching the one
// that stayed. Symlinks and non-regular files are always rejected.
func ensureEd25519KeyPair(root *os.Root, privName, pubName string) (bool, error) {
	privExists, err := inspectSecretTarget(root, privName)
	if err != nil {
		return false, err
	}
	pubExists, err := inspectSecretTarget(root, pubName)
	if err != nil {
		return false, err
	}
	switch {
	case privExists && pubExists:
		return false, nil
	case privExists != pubExists:
		return false, fmt.Errorf("only one of %s and %s exists; remove it or restore the other", privName, pubName)
	}

	pub, priv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return false, fmt.Errorf("generating Ed25519 key: %w", err)
	}
	privDER, err := x509.MarshalPKCS8PrivateKey(priv)
	if err != nil {
		return false, fmt.Errorf("encoding private key: %w", err)
	}
	pubDER, err := x509.MarshalPKIXPublicKey(pub)
	if err != nil {
		return false, fmt.Errorf("encoding public key: %w", err)
	}
	if err := writeSecretFileInRoot(root, privName, pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: privDER}), false); err != nil {
		return false, err
	}
	if err := writeSecretFileInRoot(root, pubName, pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: pubDER}), false); err != nil {
		_ = root.Remove(privName)
		return false, err
	}
	return true, nil
}

// writeSecretFileInRoot writes content to name strictly inside root, enforcing
// regular-file target semantics and setting secretFileMode on the open file
// descriptor (avoiding umask narrowing and path-based chmod races).
func writeSecretFileInRoot(root *os.Root, name string, content []byte, overwrite bool) error {
	flags := os.O_WRONLY | os.O_CREATE | os.O_EXCL
	if overwrite {
		flags = os.O_WRONLY | os.O_CREATE | os.O_TRUNC
	}

	f, err := root.OpenFile(name, flags, secretFileMode)
	if err != nil {
		return fmt.Errorf("creating secret %s: %w", name, err)
	}

	openInfo, statErr := f.Stat()
	if statErr != nil {
		_ = f.Close()
		if !overwrite {
			_ = root.Remove(name)
		}
		return fmt.Errorf("stat secret %s: %w", name, statErr)
	}
	if !openInfo.Mode().IsRegular() {
		_ = f.Close()
		return fmt.Errorf("refusing to write secret %s: opened path is not a regular file", name)
	}

	// OpenFile's perm is masked by the process umask; f.Chmod makes it exact on the open fd.
	merr := f.Chmod(secretFileMode)
	var werr error
	if merr == nil {
		_, werr = f.Write(content)
	}
	cerr := f.Close()
	if err := errors.Join(merr, werr, cerr); err != nil {
		if !overwrite {
			_ = root.Remove(name)
		}
		return fmt.Errorf("writing secret %s: %w", name, err)
	}
	return nil
}

// ensureSecretsDir creates dir with secretDirMode when it is missing and
// enforces secretDirMode (0750) even when dir already exists, so a
// pre-existing 0755 directory does not expose 0644 secret files to world-read.
func ensureSecretsDir(dir string) error {
	if err := os.MkdirAll(dir, secretDirMode); err != nil {
		return fmt.Errorf("creating secrets directory: %w", err)
	}
	if err := os.Chmod(dir, secretDirMode); err != nil {
		return fmt.Errorf("setting mode on secrets directory: %w", err)
	}
	return nil
}

// FindPendingSecrets reports the operator-provided and pki-provisioner
// secrets in dir that are missing or empty.
func FindPendingSecrets(dir string, specs []SecretSpec) (PendingSecrets, error) {
	var pending PendingSecrets
	for _, spec := range specs {
		if spec.Class == SecretClassRandom || spec.Class == SecretClassEd25519SigningKey || spec.Class == SecretClassEd25519VerifyKey {
			continue
		}
		info, err := os.Stat(filepath.Join(dir, spec.Filename))
		switch {
		case errors.Is(err, os.ErrNotExist):
		case err != nil:
			return PendingSecrets{}, fmt.Errorf("checking secret %s: %w", spec.Filename, err)
		case info.Size() > 0:
			continue
		}
		if spec.Class == SecretClassPKIProvisioner {
			pending.PKIProvisioner = append(pending.PKIProvisioner, spec)
		} else {
			pending.OperatorProvided = append(pending.OperatorProvided, spec)
		}
	}
	return pending, nil
}

// generateRandomSecret produces a URL-safe base64-encoded random string.
// Uses RawURLEncoding (no padding, no '+' or '/') so secrets are safe
// for embedding in DATABASE_URL and similar connection strings.
func generateRandomSecret(length int) (string, error) {
	buf := make([]byte, length)
	if _, err := rand.Read(buf); err != nil {
		return "", fmt.Errorf("reading random bytes: %w", err)
	}
	return base64.RawURLEncoding.EncodeToString(buf), nil
}
